<?php declare(strict_types=1);
$ct=$ivCatalogueText;
$state=input($_GET,'state');$borrower=input($_GET,'borrower');$search=input($_GET,'q');$catalogue=$inventory->loansPage($state,$borrower,$search,$_GET['loan_page']??1);$loanListBase=['view'=>'inventory','tab'=>'loans','state'=>$state,'borrower'=>$borrower,'q'=>$search];
?>
<link rel="stylesheet" href="inventory-catalogue.css?v=2">
<section class="card iv-catalogue" id="inventory-loan-catalogue"><div class="section-heading"><h2 data-inventory-loan-summary><?= e($ct('{count} Ausleihen · Seite {page} von {pages}',['count'=>$catalogue['total'],'page'=>$catalogue['page'],'pages'=>$catalogue['pages']])) ?></h2><div class="actions">
<?php if($loanWrite): ?><details class="iv-loan-mode"><summary class="btn btn-solid theme-primary"><?= e($ct('+ Ausleihe planen')) ?></summary><div><p><a class="btn btn-outline theme-secondary" href="<?= e(url($loanListBase+['new_loan'=>1])) ?>"><?= e($ct('Ab sofort reservieren')) ?></a><br><?= e($ct('Die Menge wird sofort für diese Ausleihe zurückgehalten.')) ?></p><?php if($inventory->loanWindowsReady()): ?><p><a class="btn btn-outline theme-secondary" href="<?= e(url($loanListBase+['new_loan'=>1,'timed'=>1])) ?>"><?= e($ct('Für einen Zeitraum planen')) ?></a><br><?= e($ct('Die Menge wird nur im gewählten Zeitfenster zugesagt.')) ?></p><?php endif ?></div></details><?php endif;if($ivRead)ivExport('loans',['state'=>$state,'contact'=>$borrower,'q'=>$search],$ct); ?></div></div>
<form method="get" action="#inventory-loan-catalogue" class="iv-filter"><?= hidden('view','inventory').hidden('tab','loans') ?>
<?php ivField('q',$ct('Entleiher, Nummer oder Einsatz'),$search);ivField('state',$ct('Ausleihstatus'),$state,'select',array_map($ct,[''=>'Alle','open'=>'Offene','overdue'=>'Überfällig'])+($inventory->loanWindowsReady()?array_map($ct,['planned'=>'Geplante Zeitfenster']):[])+array_map($ct,\Kulturhus\Verein\Inventory::STATES));if($ivRead)ivField('borrower',$ct('Mitglied / Kontakt'),$borrower,'select',\Kulturhus\Verein\Web\InventoryCatalogueForm::options(array_replace($personOptions,[''=>$ct('Alle Personen')]),$borrower,$ct('Ausgewählte Person nicht verfügbar – Filter prüfen'))); ?>
<button class="btn btn-outline theme-secondary"><?= e($ct('Filtern')) ?></button></form>
<div class="iv-catalogue-cards"><?php foreach($catalogue['rows']as$r): ?><article class="iv-catalogue-card" data-inventory-loan="<?= e($r['id']) ?>">
<a class="btn btn-outline theme-secondary" href="<?= e(url($loanListBase+['loan_page'=>$catalogue['page'],'loan'=>$r['id']])) ?>"><?= e(\Kulturhus\Verein\Inventory::number((int)$r['number'])) ?></a><p><?= e($r['purpose']) ?></p>
<dl><div><dt><?= e($ct('Entleiher')) ?></dt><dd><?= e($r['contact_name']) ?></dd></div><div><dt><?= e($ct('Status')) ?></dt><dd><?= e($ct(\Kulturhus\Verein\Inventory::loanStateLabel($r))) ?></dd></div><div><dt><?= e($ct('Geplante Ausgabe')) ?></dt><dd><?= e(!empty($r['window_start'])?\Kulturhus\Verein\Inventory::windowLocal($r['window_start'],'d.m.Y H:i'):dateDe($r['starts_on'])) ?></dd></div><div><dt><?= e($ct('Rückgabe bis')) ?></dt><dd class="<?= \Kulturhus\Verein\Inventory::loanOverdue($r)?'iv-low':'' ?>"><?= e(!empty($r['window_end'])?\Kulturhus\Verein\Inventory::windowLocal($r['window_end'],'d.m.Y H:i'):dateDe($r['due_on'])) ?></dd></div><div><dt><?= e($ct('Noch offen')) ?></dt><dd><?= $r['state']==='cancelled'?0:(int)$r['outstanding'] ?></dd></div></dl>
</article><?php endforeach;if(!$catalogue['rows']): ?><p><?= e($ct('Keine Ausleihen gefunden.')) ?></p><?php endif ?></div>
<nav class="iv-catalogue-pages" aria-label="<?= e($ct('Ausleihseiten')) ?>">
<?php if($catalogue['page']>1): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($loanListBase+['loan_page'=>$catalogue['page']-1])) ?>#inventory-loan-catalogue"><?= e($ct('Vorherige')) ?></a><?php endif ?>
<?php if($catalogue['page']<$catalogue['pages']): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($loanListBase+['loan_page'=>$catalogue['page']+1])) ?>#inventory-loan-catalogue"><?= e($ct('Nächste')) ?></a><?php endif ?></nav>
<form method="get" action="#inventory-loan-catalogue" class="iv-catalogue-pages"><?php foreach($loanListBase as$key=>$value)echo hidden($key,$value); ?><label><?= e($ct('Seite')) ?><input class="form-control" type="number" name="loan_page" min="1" max="<?= (int)$catalogue['pages'] ?>" value="<?= (int)$catalogue['page'] ?>" required></label><button class="btn btn-outline theme-secondary"><?= e($ct('Seite anzeigen')) ?></button></form>
</section>
